import{_ as s,o as a,c as e,ag as t}from"./chunks/framework.BwSLX4ak.js";const k=JSON.parse('{"title":"构建与开发","description":"","frontmatter":{},"headers":[],"relativePath":"shitbot/development.md","filePath":"shitbot/development.md"}'),l={name:"shitbot/development.md"};function n(p,i,h,o,d,r){return a(),e("div",null,[...i[0]||(i[0]=[t(`<h1 id="构建与开发" tabindex="-1">构建与开发 <a class="header-anchor" href="#构建与开发" aria-label="Permalink to &quot;构建与开发&quot;">​</a></h1><p>本页面面向需要从源码构建或修改 ShitBot 的开发者。普通服主应从 <a href="https://github.com/hutuyee/ShitBot/releases" target="_blank" rel="noreferrer">GitHub Releases</a> 下载发布 JAR。</p><h2 id="环境" tabindex="-1">环境 <a class="header-anchor" href="#环境" aria-label="Permalink to &quot;环境&quot;">​</a></h2><ul><li>JDK 21；</li><li>Maven 3.8 或更高版本；</li><li>可以访问 Maven Central、Spigot、BungeeCord、Velocity 和 Nukkit-MOT 依赖仓库。</li></ul><p>整个聚合工程由 JDK 21 构建，各模块输出：</p><table tabindex="0"><thead><tr><th>模块</th><th>字节码目标</th></tr></thead><tbody><tr><td>ShitBotApi</td><td>Java 8</td></tr><tr><td>ShitBotCore</td><td>Java 8</td></tr><tr><td>ShitBotRenderer</td><td>Java 8</td></tr><tr><td>ShitBotSpigot</td><td>Java 8</td></tr><tr><td>ShitBotBungee</td><td>Java 8</td></tr><tr><td>ShitBotVelocity</td><td>Java 21</td></tr><tr><td>ShitBotNukkit</td><td>Java 17</td></tr></tbody></table><h2 id="构建全部平台" tabindex="-1">构建全部平台 <a class="header-anchor" href="#构建全部平台" aria-label="Permalink to &quot;构建全部平台&quot;">​</a></h2><p>在仓库根目录执行：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mvn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">clean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> package</span></span></code></pre></div><p>版本由 <code>.mvn/maven.config</code> 中的 <code>revision</code> 属性提供。需要临时指定版本时：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mvn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Drevision</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SNAPSHOT </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">clean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> package</span></span></code></pre></div><h2 id="构建单个平台" tabindex="-1">构建单个平台 <a class="header-anchor" href="#构建单个平台" aria-label="Permalink to &quot;构建单个平台&quot;">​</a></h2><p>使用 <code>-am</code> 同时构建依赖的 ShitBotApi 与 ShitBotCore：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mvn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pl ShitBotSpigot </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">am package</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mvn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pl ShitBotBungee </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">am package</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mvn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pl ShitBotVelocity </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">am package</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mvn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pl ShitBotNukkit </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">am package</span></span></code></pre></div><p>最终插件 JAR 位于对应模块的 <code>target/</code>。不要发布 <code>original-*.jar</code>、sources、javadoc 或 test JAR。</p><h2 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to &quot;测试&quot;">​</a></h2><p>测试使用 JUnit 4.13.2 和 Maven Surefire 3.5.2，位于各模块的 <code>src/test/java/</code>。带测试的模块要求至少发现一个测试，避免测试目录或命名错误导致构建空跑。</p><p>只运行 API、Core 和 Renderer 的共享逻辑测试，无需服务端 API 仓库：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mvn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pl ShitBotApi</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ShitBotCore</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ShitBotRenderer </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">am test</span></span></code></pre></div><p>使用 JDK 21 运行全部测试并检查所有平台的打包：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mvn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">clean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> verify</span></span></code></pre></div><p>当前用例覆盖：</p><ul><li>API 输入副本、只读集合、渲染结果字节隔离和数据提供器 ID 校验；</li><li>控制台消息序列化、协议版本、非法枚举/长度/列表、HMAC 认证和挑战值绑定；</li><li>占位符 Unicode 往返、重复键、损坏数据和大小限制；</li><li>语言回退、语言文件路径、快捷命令别名冲突与超时配置；</li><li>背包格式 1/2/3 兼容、物品组件、槽位归一化和 GZIP 解压大小限制；</li><li>模板绑定、YAML 校验、发布快照、回滚、资源路径和资源大小限制；</li><li>无界面 PNG 渲染、条件/循环、渲染超时和展开图层数量限制；</li><li>Folia 调度方法签名的兼容与拒绝路径。</li></ul><p>这些测试使用内存数据和临时目录，不启动 Minecraft、OneBot、数据库或编辑器服务，也不访问远程图片。渲染测试只断言简单形状的内部像素，避免依赖系统字体。真实平台行为和外部服务联调仍需单独验证。</p><p>Surefire 的 XML 和文本报告位于各模块的 <code>target/surefire-reports/</code>。</p><h2 id="模块结构" tabindex="-1">模块结构 <a class="header-anchor" href="#模块结构" aria-label="Permalink to &quot;模块结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ShitBot/</span></span>
<span class="line"><span>├─ ShitBotApi/        # 绑定、白名单、图片 API 与渲染 SPI，独立发布供开发者依赖</span></span>
<span class="line"><span>├─ ShitBotCore/       # OneBot、数据库、绑定、图片、更新和共享业务逻辑</span></span>
<span class="line"><span>├─ ShitBotRenderer/   # 单独发布并按需下载的高级 Java2D 场景渲染器与编辑器</span></span>
<span class="line"><span>├─ ShitBotSpigot/     # Bukkit、Paper、Folia 与后端命令监听</span></span>
<span class="line"><span>├─ ShitBotBungee/     # BungeeCord 平台入口</span></span>
<span class="line"><span>├─ ShitBotVelocity/   # Velocity 平台入口</span></span>
<span class="line"><span>├─ ShitBotNukkit/     # Nukkit-MOT 平台入口</span></span>
<span class="line"><span>├─ PictureBridge/     # 独立客户端模组的 Git 子模块</span></span>
<span class="line"><span>├─ docs/              # 项目文档</span></span>
<span class="line"><span>└─ pom.xml            # Maven 聚合工程</span></span></code></pre></div><p>平台模块依赖 ShitBotCore，并将运行所需的共享依赖重定位到最终 JAR。平台 API 依赖以 provided 范围使用，不应打包进发布 JAR。<code>ShitBotRenderer</code> 不得成为平台模块依赖；它通过 <code>ShitBotApi</code> 的 SPI 在运行时隔离加载，否则会破坏默认插件的体积边界和按需下载语义。</p><h2 id="配置资源" tabindex="-1">配置资源 <a class="header-anchor" href="#配置资源" aria-label="Permalink to &quot;配置资源&quot;">​</a></h2><p>各平台默认配置位于：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ShitBotSpigot/src/main/resources/</span></span>
<span class="line"><span>ShitBotBungee/src/main/resources/</span></span>
<span class="line"><span>ShitBotVelocity/src/main/resources/</span></span>
<span class="line"><span>ShitBotNukkit/src/main/resources/</span></span></code></pre></div><p>修改配置结构时，应同步检查：</p><ul><li>四个平台的 <code>config.yml</code>；</li><li>平台适用的 <code>commands.yml</code>；</li><li>Core 中共享的 <code>lang/zh_CN.yml</code> 与 <code>lang/en_US.yml</code>；</li><li>Core 中共享的 <code>templates/default.yml</code>；</li><li>配置加载器与默认值；</li><li>重载流程；</li><li>本文档中引用的配置示例。</li></ul><p>Nukkit-MOT 不包含代理—后端传输配置，其他平台的 <code>commands.yml</code> 共享同一配置结构。</p><h2 id="picturebridge-子模块" tabindex="-1">PictureBridge 子模块 <a class="header-anchor" href="#picturebridge-子模块" aria-label="Permalink to &quot;PictureBridge 子模块&quot;">​</a></h2><p>PictureBridge 是独立仓库和独立构建，不参与 ShitBot Maven 聚合工程。只修改服务端插件时，不需要构建 PictureBridge。</p><p>需要同时开发客户端模组时，克隆仓库后初始化子模块：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git submodule update </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">init </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">recursive</span></span></code></pre></div><p>PictureBridge 的构建说明见其独立仓库文档。</p><h2 id="ci-与-release" tabindex="-1">CI 与 Release <a class="header-anchor" href="#ci-与-release" aria-label="Permalink to &quot;CI 与 Release&quot;">​</a></h2><p>GitHub Actions 在 push、pull request 和手动触发时：</p><ol><li>在 Linux JDK 8、17 和 Windows JDK 21 上运行 API、Core、Renderer 的 <code>clean verify</code>；</li><li>在 Linux JDK 21 上执行全工程 <code>mvn clean verify</code>，包含 Spigot 调度适配器测试和四个平台打包；</li><li>无论成功或失败，都汇总测试结果并上传已有的 Surefire 报告，保留 14 天；预期模块没有报告、没有执行任何测试或全部跳过时会失败；</li><li>收集四个平台 JAR、一个 <code>ShitBotApi</code> JAR 和一个独立 <code>ShitBotRenderer</code> JAR，生成并校验 SHA-256 文件；</li><li>检查项目类的 Java 字节码目标、入口和共享资源、Renderer SPI 与版本信息，以及平台 API、测试依赖和可选 Renderer 的打包隔离；</li><li>上传发布构件 Artifact，保留 30 天。</li></ol><p>矩阵任务不会因其他环境失败而提前取消；同一分支或 PR 的过期 CI 运行会被新运行取消。所有测试和构建统一汇总为 <code>CI checks</code>，可将它设为分支保护的必需检查。工作流使用只读仓库权限，只有 Release 上传任务获得写权限。</p><p>发布 GitHub Release 时，工作流还会：</p><ol><li>执行相同的测试矩阵和全平台构建，不跳过测试；只有 <code>CI checks</code> 成功才允许上传；</li><li>使用仓库 Secret 中的 RSA 私钥签署四个平台 JAR、公开 API JAR 和可选渲染器 JAR；</li><li>检查六个 JAR、六个 checksum 和六个签名，并使用当前 Release 源码中的内置公钥逐个验签；</li><li>将 JAR、<code>.sha256</code> 和 <code>.sig</code> 上传到 Release。Release 工作流不会被新运行自动取消。</li></ol><p>工作流在 <code>.github/workflows/release.yml</code> 中维护；测试报告汇总和发布构件检查位于 <code>.github/scripts/</code>，只依赖 Python 3 标准库。PictureBridge 保持独立 CI，不参与上述 Maven 测试与打包。</p><p>签名密钥管理见<a href="/docs/shitbot/updating.html">升级与自动更新</a>。</p><h2 id="发布前文档" tabindex="-1">发布前文档 <a class="header-anchor" href="#发布前文档" aria-label="Permalink to &quot;发布前文档&quot;">​</a></h2><p>发布包含配置变更的版本时，应在 Release Notes 明确说明：</p><ul><li>是否需要重新生成或补充 <code>config.yml</code>；</li><li>是否需要同步更新代理与后端；</li><li>数据库是否发生迁移；</li><li>Java 或平台最低版本是否变化；</li><li>是否新增权限、端口或外部网络依赖。</li></ul><h2 id="双语文档维护" tabindex="-1">双语文档维护 <a class="header-anchor" href="#双语文档维护" aria-label="Permalink to &quot;双语文档维护&quot;">​</a></h2><p>中文文档保留在 <code>README.md</code> 和 <code>docs/*.md</code>，英文文档位于 <code>README.en.md</code> 和 <code>docs/en/*.md</code>，手册文件名一一对应。更新功能说明时同步维护两种语言，并保留每页顶部的语言链接。</p><p>网站仓库通过 <code>npm run docs:sync -- ../ShitBot</code> 同时复制中英文手册到对应语言目录。通用模板示例仍放在 <code>docs/examples/</code>。</p>`,53)])])}const g=s(l,[["render",n]]);export{k as __pageData,g as default};
